import{z as A,x as B,o as p,c as r,q as n,j as s,D as i,d as E,s as t,S as o,b as e}from"./chunks/framework.C8m1ZpeB.js";const P=JSON.parse('{"title":"菲利普斯曲线与预期","description":"","frontmatter":{"title":"菲利普斯曲线与预期","date":"2026-09-08T00:00:00.000Z","section":"econ"},"headers":[],"relativePath":"econ/phillips-expectations.md","filePath":"econ/phillips-expectations.md","lastUpdated":1791063341000}'),u={name:"econ/phillips-expectations.md"};function d(h,a,m,F,C,D){const l=B("Mermaid");return p(),r("div",null,[a[2]||(a[2]=n('<h1 id="菲利普斯曲线与预期" tabindex="-1">菲利普斯曲线与预期 <a class="header-anchor" href="#菲利普斯曲线与预期" aria-label="Permalink to &quot;菲利普斯曲线与预期&quot;">​</a></h1><div class="epigraph"><p>失业与工资膨胀的替换，一旦写进预期，就变成一条随政策移动的曲线，而不是可以钉住的菜单。</p><footer>—— Phillips, The Relation between Unemployment and the Rate of Change of Money Wage Rates, Economica 1958；Friedman, AER 1968；Lucas 的理性预期推进</footer></div><p><a href="/econ/seigniorage">上一课</a>（通胀税与铸币税）。在此之上，通胀写成对实际余额的税。税可以改变持币，不能永久改变<a href="/econ/natural-unemployment">自然率</a>。本课的缺口是：观测上 \\(\\pi\\) 与 \\(u\\) 为何短相关、长脱钩。Phillips 给出工资–失业的统计替换；Friedman 与 Phelps 把预期加进去；Lucas 再把预期写成对政策规则的推断。IS–LM 用这条曲线当供给侧的缺口，但先把预期钉住。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>Phillips（1958）在英国数据里看到货币工资变化率与失业的负向关系。若直接把这条曲线当政策菜单，「多一点通胀、少一点失业」就像在需求曲线上选点。自然率课已经拒绝永久菜单。缺口是写出</p> \\[\\pi_t = \\pi_t^e + \\kappa(u_t-u^*)+\\varepsilon_t, \\]<p>使 \\(u=u^*\\) 且 \\(\\pi^e=\\pi\\) 时没有加速，也没有永久替换。\\(\\kappa\\) 的微观来自工资或价格调整，本课不先上 Calvo。</p><p>Friedman（1968）：扩张先造成意外通胀，实际工资或相对价格被误读，\\(u\\) 暂时低于 \\(u^*\\)；预期追上后替换消失，\\(\\pi\\) 停在更高水平。Phelps 从工资设定走到同类结论。Lucas（1972/1973）让预期成为对总价格与相对价格的最优滤波：只有未被预见的货币才动 \\(y\\)。</p><p><span class="marginnote">直觉类比：\\(\\pi^e\\) 是工人签工资合同时「脑中预设的物价涨幅」。若央行把所有物价一起推高，工人只看到自己的名义工资涨了，误以为是相对工资变贵，于是多干活——其实购买力没变。意外通胀买来的短暂就业，靠的就是这种集体错觉；预期一旦追上，错觉失灵。</span></p><p><span class="marginnote">加速主义：要把 \\(u\\) 维持在 \\(u^*\\) 之下，必须让 \\(\\pi\\) 持续高于 \\(\\pi^e\\)，于是 \\(\\pi\\) 本身加速。NAIRU 是操作上「不加速」的 \\(u\\)，估计依赖这条式子的设定。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>附加预期的菲利普斯把供给写成意外通胀对缺口的反应。需求侧是后课 IS–LM 或欧拉–NK。本课只关闭供给：给定 \\(\\pi^e\\)，需求拉动可以沿短曲线移动；\\(\\pi^e\\) 一变，整条短曲线移动。</p><p>适应性预期把 \\(\\pi^e\\) 写成滞后 \\(\\pi\\) 的加权；理性预期让 \\(\\pi^e\\) 等于模型给出的条件期望。政策含义立刻分叉：适应性下，渐进消通胀有失业代价；理性下，可信的规则可以改变 \\(\\pi^e\\) 而不必走完同一条牺牲比——这已经碰到卢卡斯批判，本课点到为止。</p>',13)),(p(),s(o,null,{default:i(()=>[t(l,{id:"mermaid-35",class:"mermaid",graph:"flowchart%20TD%0A%20%20PH%5B%22Phillips%20%E7%BB%9F%E8%AE%A1%E6%9B%BF%E6%8D%A2%22%5D%20--%3E%20EXP%5B%22%E9%99%84%E5%8A%A0%20%CF%80%5Ee%22%5D%0A%20%20EXP%20--%3E%20NAT%5B%22u*%EF%BC%9A%CF%80%3D%CF%80%5Ee%20%E6%97%B6%E6%97%A0%E6%9B%BF%E6%8D%A2%22%5D%0A%20%20EXP%20--%3E%20LUC%5B%22%E5%8F%AA%E6%9C%89%E6%84%8F%E5%A4%96%E8%B4%A7%E5%B8%81%E5%8A%A8%20y%22%5D%0A%20%20NAT%20--%3E%20LONG%5B%22%E9%95%BF%E6%9C%9F%E5%9E%82%E7%9B%B4%22%5D%0A"})]),fallback:i(()=>[...a[0]||(a[0]=[E(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=e("p",null,"工资 Phillips 与价格 Phillips 差一个单位劳动成本与加成。本课用 \\(\\pi\\) 对 \\(u-u^*\\)，声明指数来自价格课。供给冲击 \\(\\varepsilon\\) 使 \\(\\pi\\) 与 \\(u\\) 同向恶化，不能再用需求菜单解释。",-1)),a[4]||(a[4]=e("h3",{id:"预期不是装饰",tabindex:"-1"},[E("预期不是装饰 "),e("a",{class:"header-anchor",href:"#预期不是装饰","aria-label":'Permalink to "预期不是装饰"'},"​")],-1)),a[5]||(a[5]=e("p",null,"若把 \\(\\pi^e\\) 固定，短曲线看起来稳定，用它做最优控制会得到「微调失业」。一旦公众把规则学进去，\\(\\pi^e\\) 成为规则的函数，估计出来的替换消失。后课卢卡斯批判把这句话变成对所有简化式的警告。",-1)),a[6]||(a[6]=e("h2",{id:"机制",tabindex:"-1"},[E("机制 "),e("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[7]||(a[7]=e("p",null,"意外的名义扩张改变了被感知的相对价格：厂商以为自己的产品更值钱，或工人以为实际工资更高，就业暂时上升。当一般物价被正确感知，配置回到 \\(y^*\\)，\\(u\\) 回到 \\(u^*\\)，多出来的只是 \\(\\pi\\)。铸币税仍在：更高的稳态 \\(\\pi\\) 继续抽实际余额的税，但抽不到永久的低失业。",-1)),a[8]||(a[8]=e("p",null,"一次意外扩张从得手到失效的完整时序：",-1)),(p(),s(o,null,{default:i(()=>[t(l,{id:"mermaid-54",class:"mermaid",graph:"flowchart%20TD%0A%20%20Z%5B%22%E5%A4%AE%E8%A1%8C%E6%84%8F%E5%A4%96%E6%89%A9%E5%BC%A0%E8%B4%A7%E5%B8%81%22%5D%20--%3E%20A%5B%22%E7%89%A9%E4%BB%B7%E6%B6%A8%E5%BE%97%E6%AF%94%E9%A2%84%E6%9C%9F%E5%BF%AB%EF%BC%9A%CF%80%20%E9%AB%98%E4%BA%8E%20%CF%80%5Ee%22%5D%0A%20%20A%20--%3E%20B%5B%22%E5%8E%82%E5%95%86%E4%B8%8E%E5%B7%A5%E4%BA%BA%E8%AF%AF%E8%AF%BB%E7%9B%B8%E5%AF%B9%E4%BB%B7%E6%A0%BC%22%5D%0A%20%20B%20--%3E%20C%5B%22%E5%B0%B1%E4%B8%9A%E4%B8%8A%E5%8D%87%EF%BC%9Au%20%E6%9A%82%E6%97%B6%E4%BD%8E%E4%BA%8E%20u*%22%5D%0A%20%20C%20--%3E%20D%5B%22%E5%85%AC%E4%BC%97%E9%80%90%E8%BD%AE%E4%BF%AE%E6%AD%A3%E9%A2%84%E6%9C%9F%EF%BC%9A%CF%80%5Ee%20%E4%B8%8A%E7%A7%BB%22%5D%0A%20%20D%20--%3E%20E%5B%22%E5%AE%9E%E9%99%85%E5%B7%A5%E8%B5%84%E5%9B%9E%E5%88%B0%E5%8E%9F%E4%BD%8D%EF%BC%9Au%20%E5%9B%9E%E5%88%B0%20u*%22%5D%0A%20%20E%20--%3E%20F%5B%22%E5%8F%AA%E5%89%A9%E6%9B%B4%E9%AB%98%E7%9A%84%20%CF%80%EF%BC%9A%E7%9F%AD%E6%9C%9F%E6%9B%BF%E6%8D%A2%E6%B6%88%E5%A4%B1%22%5D%0A"})]),fallback:i(()=>[...a[1]||(a[1]=[E(" Loading... ",-1)])]),_:1})),a[9]||(a[9]=n('<p><span class="marginnote">数字实例：想让失业一年都压在自然率之下，通胀必须年年高过公众的预期；公众吃过亏后预期跟着上调，第二年就得拿出更高的通胀才能再骗一次。于是通胀不是停在某个高位，而是逐年往上加速——「加速主义」的名字就是这么来的，NAIRU 就是加速恰好不发生的那一点失业率。</span></p><p>长期垂直不是经验上每个样本的回归斜率，而是理论要求：预期正确时实际变量由实物与自然率决定。1970 年代的滞胀是对「稳定负斜率菜单」的拒绝，不是对短替换的否认。</p><p>供给冲击 \\(\\nu\\) 使 \\(\\pi\\) 与 \\(u\\) 同升，原始负斜率破裂。要把 \\(\\nu\\) 写进方程。加速主义：保持 \\(u\\lt u^*\\) 必须让 \\(\\pi\\) 持续高于 \\(\\pi^e\\)。可信的低 \\(\\pi\\) 目标降低 \\(\\pi^e\\)，同样缺口对应更低的 \\(\\pi\\)。</p><p><span class="marginnote">常见误区：1970 年代的滞胀（高通胀与高失业并存）并没有推翻短期替换关系，它推翻的是把负斜率曲线当成固定菜单。供给冲击把整条曲线上推，通胀与失业同时恶化；沿一条假想不变的菜单「选点」做微调的政策思路随之破产。</span></p><p><span class="marginnote">原始 Phillips 用工资变化；政策讨论常用价格通胀。传递取决于加成与生产率。斜率不是深结构——卢卡斯批判后课宣判简化式。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不估计牺牲比，不把新凯恩斯的前瞻 Phillips 整条搬进来——那里要有欧拉与 Calvo，是后课。也不把劳动市场匹配写成量化栏的订单簿。自然率可以慢变；把一切 \\(u\\) 上升写成预期错误，会放过 \\(u^*\\) 的结构移动。开放程度与锚定会改 \\(\\kappa\\)，不能把 1960 年代美国的斜率抄到另一国。</p><p>后课默认：谈短期通胀–缺口时，必写 \\(\\pi^e\\)；谈长期时曲线在 \\(u^*\\) 垂直。下一课用 Hicks 的 IS–LM 把需求侧写成会计式的商品与货币均衡。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>Phillips 的统计替换加上 \\(\\pi^e\\) 后，长期没有失业–通胀菜单。</li><li>自然率：\\(u=u^*\\) 且预期正确时，\\(\\pi\\) 由货币趋势等名义锚决定。</li><li>只有意外的名义冲击暂时移动 \\(y\\)、\\(u\\)。</li><li>供给冲击会让相关变号；加速主义拒绝永久菜单。</li><li>简化式替换随政策规则而动，是卢卡斯批判的入口。</li><li>出处：Phillips, Economica 1958；Lucas 理性预期与中性。</li></ul>',10))])}const f=A(u,[["render",d]]);export{P as __pageData,f as default};
